package work.solour.pulse;
public class EngineTest {
 static int checks=0;static void ok(boolean b,String m){checks++;if(!b)throw new AssertionError(m);} static Engine e(String scene){Engine e=new Engine();e.scene=scene;e.running=true;return e;}static void ticks(Engine e,int n,int hr){for(int i=0;i<n;i++){long t=(e.seconds+1)*1000L;e.heart(hr,t);e.tick(t);}}
 public static void main(String[] a){
 ok(Engine.parseHr(new byte[]{0,(byte)180})==180,"8 bit");ok(Engine.parseHr(new byte[]{1,44,1})==300,"16 bit");try{Engine.parseHr(new byte[]{1,4});throw new AssertionError();}catch(IllegalArgumentException expected){checks++;}
 Engine e=e("跑步机");e.heart(120,0);e.velocity(2,0);for(int i=1;i<=11;i++)e.tick(i*1000);ok(e.valid==10,"HR stops after ten seconds");ok(!e.freshHr(11000),"stale missing");ok(e.distance==10,"speed stops after 5 seconds");e.manualKmh=3.6;e.tick(12000);ok(e.distance==11&&e.estimatedUsed,"manual fallback labelled");e.pause();double d=e.distance;int sec=e.seconds;e.tick(13000);ok(e.distance==d&&e.seconds==sec,"pause freezes time and distance");e.pause();e.disconnect();ok(!e.freshHr(13000),"disconnect missing no simulation");ok(!e.simulated,"no implicit simulation");
 e=e("器械");ticks(e,20,90);ok(e.baseN==20&&e.baseline==90,"20-second baseline");ticks(e,7,150);ok(e.groupStart<0,"rise persistence");ticks(e,5,150);ok(e.groupStart>=0&&e.inferred,"inferred start");ticks(e,25,150);ticks(e,20,100);ok(e.groups.size()==1&&e.pending()==1&&e.confirmed==0,"inferred end pending only");e.confirm(0);e.confirm(0);ok(e.confirmed==1,"confirm once");e.delete(0);ok(e.confirmed==0&&e.groups.isEmpty(),"delete corrected");
 e=e("器械");ticks(e,20,90);ticks(e,5,150);e.pause();e.pause();ok(e.rise==0,"pause breaks rise");e.heart(180,26000);e.tick(26000);ok(e.warning&&e.rise==0&&e.groupStart<0,"warning blocks guesses");e.tick(50000);ok(e.rise==0&&!e.warning,"missing blocks guesses");e.startGroup(false);ticks(e,5,100);ok(e.confirmed==0,"unfinished never completed implicitly");e.finishGroup();ok(e.confirmed==1&&!e.groups.get(0).guessed,"manual complete");
 e=e("单车");ticks(e,7,150);ok(e.band==0,"8 second cycling buffer");ticks(e,1,150);ok(e.band==2,"cycling transition");ticks(e,19,90);ok(e.band==2,"20 second minimum switch spacing");ticks(e,1,90);ok(e.band==0,"cycling cooldown complete");
 e=e("跑步机");ticks(e,11,150);ok(e.band==0,"12 second treadmill buffer");ticks(e,1,150);ok(e.band==2,"treadmill transition");ticks(e,29,90);ok(e.band==2,"30 second minimum");ticks(e,1,90);ok(e.band==0,"treadmill cooldown");e.heart(180,43000);e.tick(43000);ok(e.band==0&&e.warning,"warning immediate calm");
 e=e("器械");e.restDefault=30;e.startRest();int calls=0;for(int i=1;i<=30;i++){e.tick(i*1000);calls+=e.countdown.size();}ok(calls==5&&e.restDone&&e.groupStart<0,"countdown and no automatic next group");e.startRest();e.restPaused=true;e.tick(31000);ok(e.rest==30,"rest pause");e=e("单车");ticks(e,179,100);ok(!e.encourage(),"no early encouragement");ticks(e,1,100);ok(e.encourage(),"180 sec encouragement");ok(!e.encourage(),"no duplicate encouragement");
 System.out.println("PASS "+checks+" algorithm and session-flow assertions");}
}
